shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tokio-util/tests/time_delay_queue.rs')
text = path.read_text()
anchor = '#[tokio::test(start_paused = true)]\nasync fn compact_expire_empty() {'
addition = '''#[tokio::test(start_paused = true)]
async fn remove_last_item_wakes_poller() {
    let mut queue = task::spawn(DelayQueue::new());
    let key = queue.insert("foo", ms(100));

    assert_pending!(poll!(queue));
    assert!(!queue.is_woken());

    assert_eq!(queue.remove(&key).into_inner(), "foo");

    assert!(queue.is_woken());
    assert!(assert_ready!(poll!(queue)).is_none());
}

#[tokio::test(start_paused = true)]
async fn try_remove_last_item_wakes_poller() {
    let mut queue = task::spawn(DelayQueue::new());
    let first = queue.insert("foo", ms(100));
    let last = queue.insert("bar", ms(200));

    assert_pending!(poll!(queue));
    assert!(!queue.is_woken());

    assert_eq!(queue.try_remove(&first).unwrap().into_inner(), "foo");
    assert!(!queue.is_woken());
    assert_pending!(poll!(queue));

    assert!(queue.try_remove(&first).is_none());
    assert!(!queue.is_woken());

    assert_eq!(queue.try_remove(&last).unwrap().into_inner(), "bar");

    assert!(queue.is_woken());
    assert!(assert_ready!(poll!(queue)).is_none());
}

'''
assert text.count(anchor) == 1
path.write_text(text.replace(anchor, addition + anchor))
PY
cargo test -p tokio-util --features full --test time_delay_queue last_item_wakes_poller --offline

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('tokio-util/src/time/delay_queue.rs')
text = path.read_text()
changes = [
    ('''    /// removed item as well as the `Instant` at which it will the delay will
    /// have expired.
''', '''    /// removed item as well as the `Instant` at which it will the delay will
    /// have expired.
    ///
    /// If this removal makes the queue empty, the task registered with
    /// [`Self::poll_expired`] is woken.
'''),
    ('''        Expired {
            key: Key::new(key.index),
''', '''        if self.is_empty() {
            if let Some(waker) = self.waker.take() {
                waker.wake();
            }
        }

        Expired {
            key: Key::new(key.index),
'''),
    ('''    /// Returns `None` if `key` is not in the queue.
''', '''    /// Returns `None` if `key` is not in the queue.
    ///
    /// If this removal makes the queue empty, the task registered with
    /// [`Self::poll_expired`] is woken.
'''),
]
for old, new in changes:
    assert text.count(old) == 1
    text = text.replace(old, new)
path.write_text(text)
PY
cargo test -p tokio-util --features full --test time_delay_queue --offline && git diff --check && git --no-pager diff --stat

